rollout=str(root/'run/rollout.py');sim=str(root/'run/simulator.py')
def matches(target):
 pids=[]
 for p in pathlib.Path('/proc').iterdir():
  if not p.name.isdigit():continue
  try:args=(p/'cmdline').read_bytes().split(b'\x00')
  except OSError:continue
  if target.encode() in args:pids.append(int(p.name))
 return pids
